#!/usr/bin/env python3
"""Conversation fallback for the Raspberry Pi music DJ.

When pi_command_daemon has ruled out concrete radio actions, this module treats
the utterance as a short human conversation: answer in one or two lines, show it
on Whisplay, and only speak when the user's situation looks important.
"""
import json
import os
import re
import urllib.error
import urllib.request


API_BASE = os.environ.get("SUNSET_API", "http://127.0.0.1:8080").rstrip("/")
ENABLED = os.environ.get("SUNSET_CHAT_FALLBACK", "1").lower() not in {"0", "false", "no", "off"}
TIMEOUT = float(os.environ.get("SUNSET_CHAT_TIMEOUT", "8"))
REPLY_MAX = int(os.environ.get("SUNSET_CHAT_REPLY_MAX", "70"))
SEARCH = os.environ.get("SUNSET_CHAT_RAG", "1").lower() not in {"0", "false", "no", "off"}

CHAT_SYSTEM = (
    "你是日落电台里的音乐 DJ，温柔、克制，懂音乐也懂人。"
    "用户在随便跟你说话或问问题。请用一两句口语化中文自然回应，"
    "像正在小声陪他说话。你的回应有时会被读出来，所以要短。"
    "不要报功能菜单，不要说自己是 AI 或程序，不要用括号和表情符号。"
    "如果用户像是在点歌、切城市、调音量或建立电台，就顺着回应，轻轻提示他可以直接说出来。"
)

LOCAL_REPLIES = [
    "嗯，我在听，你接着说。",
    "我记下了。想听点什么，直接跟我说城市或心情就行。",
    "这会儿信号有点弱，不过我还在你这儿。",
    "好，我陪着你。要不要我接一首歌？",
    "听见了。今晚想要松一点，还是热闹一点？",
]


