    r"(?:文字|打字|写字)(?:回|回复|回答|告诉|说|讲)?(?:我)?(?:就好|就行)?|"
    r"只(?:打字|写字|文字|写屏(?:幕)?|显示(?:文字)?|看屏幕|在屏幕)|"
    r"屏幕上(?:回|说|告诉|显示)?|打(?:在|到)?屏幕(?:上)?|"
    r"(?:小声|轻声|低声|默默|悄悄)(?:回|回复|回答|告诉|说|讲)?(?:我)?|"
    r"安静(?:点|一点)?(?:回|回复|回答|告诉|说|讲)?(?:我)?|"
    r"显示屏上(?:就行)?|只亮屏|亮屏(?:一下)?"
    r")"
    r"(?:[，,。.!！?？\s]*(?:告诉我|跟我说|说说|讲讲|帮我|给我|回我|查一下|看一下|列一下|一下))*"
