def _quiet_priority_reply(text):
    if re.search(r"(?:要不要|需不需要|会不会|能不能).{0,4}(?:念|读出来|朗读|播报|出声|走语音)", text, re.I):
        return ""
    if not SILENT_REQUEST_RE.search(text):
        return ""
    if FAILURE_GUARDRAIL_RE.search(text):
        return QUIET_FAILURE_GUARDRAIL_REPLY
    if PORTABLE_PLACE_HELP_RE.search(text):
        return QUIET_PORTABLE_PLACE_REPLY
    if LOW_BATTERY_PLAYBACK_RE.search(text):
        return LOW_BATTERY_PLAYBACK_REPLY
    if LOW_BATTERY_QUIET_EXTRA_RE.search(text):
        return QUIET_LOW_BATTERY_REPLY
    if PLAYBACK_CONTROL_RE.search(text):
        return PLAYBACK_CONTROL_REPLY
    if LOW_BATTERY_HELP_RE.search(text):
        return QUIET_LOW_BATTERY_REPLY
    if WAY_HOME_HELP_RE.search(text):
        return QUIET_WAY_HOME_REPLY
    if BUTTON_GESTURE_RE.search(text):
        return QUIET_BUTTON_GESTURE_REPLY
    return ""


def _intent_text(text):
    raw = str(text or "").strip()
    candidate = raw
    for _ in range(3):
        stripped = LEADING_QUIET_INTENT_RE.sub("", candidate, count=1).strip(" \t\r\n，,。.!！?？")
        if stripped == candidate:
            break
        candidate = stripped
    return candidate or raw


def _intent_match(pattern, raw, intent):
    return bool(pattern.search(raw) or (intent != raw and pattern.search(intent)))


def _router_priority_match(raw, intent):
    if not (
        _intent_match(ACTION_ROUTER_RE, raw, intent)
        or _intent_match(LOW_CONFIDENCE_ACTION_GUARD_RE, raw, intent)
    ):
        return False
    return not re.search(r"(失败|报错|跑坏|没跑通|没成功|挂了|坏了|不可用|不存在|没装|找不到)", raw, re.I)


def _info_followup_match(raw, intent):
    return bool(
        NO_ACTION_CURRENT_STATUS_RE.search(raw)
        or NO_ACTION_ROUTE_STATUS_RE.search(raw)
        or NO_ACTION_PLAYLIST_STATUS_RE.search(raw)
        or NO_ACTION_NEXT_CITY_PLAYLIST_REASON_RE.search(raw)
        or NO_ACTION_PREVIOUS_CITY_PLAYLIST_REASON_RE.search(raw)
        or NO_ACTION_PREVIOUS_SONG_STORY_RE.search(raw)
        or NO_ACTION_PREVIOUS_TRACK_STATUS_RE.search(raw)
        or _intent_match(CURRENT_LOCATION_FOLLOWUP_RE, raw, intent)
        or _intent_match(CURRENT_TRACK_FOLLOWUP_RE, raw, intent)
        or _intent_match(SONG_STORY_FOLLOWUP_RE, raw, intent)
        or _intent_match(CITY_STORY_FOLLOWUP_RE, raw, intent)
        or _intent_match(ROUTE_FOLLOWUP_RE, raw, intent)
        or _intent_match(PLAYLIST_FOLLOWUP_RE, raw, intent)
        or _intent_match(NEXT_CITY_PLAYLIST_REASON_RE, raw, intent)
        or _intent_match(PREVIOUS_CITY_PLAYLIST_REASON_RE, raw, intent)
        or _intent_match(PREVIOUS_CITY_PLAYLIST_FOLLOWUP_RE, raw, intent)
    )


def _keyword_reply(raw, intent, allowed_replies=None):
    lowered_candidates = (str(raw or "").lower(),)
    if intent != raw:
        lowered_candidates += (str(intent or "").lower(),)
    for keywords, reply in KEYWORD_REPLIES:
        if allowed_replies is not None and reply not in allowed_replies:
            continue
        if any(keyword.lower() in candidate for keyword in keywords for candidate in lowered_candidates):
            return reply
    return ""


def _clean_reply(text):
    reply = " ".join(str(text or "").split()).strip()
    for left, right in (("“", "”"), ('"', '"'), ("「", "」")):
        if reply[:1] == left and reply[-1:] == right:
            reply = reply[1:-1].strip()
    return reply[:REPLY_MAX]


def _llm_reply(text):
    payload = json.dumps({"system": CHAT_SYSTEM, "prompt": text, "json": False, "search": SEARCH}).encode("utf-8")
    request = urllib.request.Request(
        API_BASE + "/api/frost-llm",
        data=payload,
        headers={"content-type": "application/json"},
        method="POST",
    )
    with urllib.request.urlopen(request, timeout=TIMEOUT) as response:
        data = json.loads(response.read().decode("utf-8"))
    return _clean_reply(data.get("text"))


def _local_reply(text):
    raw = str(text or "")
    intent = _intent_text(raw)
    if NO_ACTION_AUDIO_PRIVACY_STATUS_RE.search(raw):
        return VOICE_PRIVACY_REPLY
    if NO_ACTION_CAMERA_PRIVACY_STATUS_RE.search(raw):
        return AMBIENT_MANUAL_CONSENT_REPLY
    if MEMORY_PRIVACY_PRIORITY_RE.search(raw):
        return MEMORY_BOUNDARY_REPLY
    if VOICE_PRIVACY_RE.search(raw):
        return VOICE_PRIVACY_REPLY
    if AMBIENT_MANUAL_CONSENT_RE.search(raw):
        return AMBIENT_MANUAL_CONSENT_REPLY
    if AMBIENT_SCAN_RE.search(raw):
        return AMBIENT_SCAN_REPLY
    if MUTE_GUARD_RE.search(raw):
        return MUTE_GUARD_REPLY
    if TTS_DECISION_PRIORITY_RE.search(raw):
        return FROST_TTS_DECISION_REPLY
    quiet_priority_reply = _quiet_priority_reply(raw)
    if quiet_priority_reply:
        return quiet_priority_reply
    if _intent_match(ACTION_FAILURE_SAFETY_RE, raw, intent):
        return FAILURE_GUARDRAIL_REPLY
    if AUDIO_PRIVACY_QUESTION_RE.search(raw) and not _info_followup_match(raw, intent):
        return AUDIO_POLICY_REPLY
    if WAKE_SOURCE_CANCEL_RE.search(raw):
        return WAKE_SOURCE_CANCEL_REPLY
    if WAKE_SOURCE_GUARD_RE.search(raw):
        return WAKE_SOURCE_GUARD_REPLY
    if NO_ACTION_PREVIOUS_DISPATCH_RE.search(raw):
        return ACTION_STATUS_REPLY
    if VOICE_STATUS_RE.search(raw):
        return VOICE_STATUS_REPLY
    if AUDIO_MODE_STATUS_RE.search(raw):
        return AUDIO_MODE_REPLY
    if WAKE_WORD_GUIDE_RE.search(raw):
        return WAKE_WORD_GUIDE_REPLY
    if WAKE_WINDOW_RE.search(raw):
        return WAKE_WINDOW_REPLY
    if BUTTON_GESTURE_RE.search(raw):
        return BUTTON_GESTURE_REPLY
    if _intent_match(LOW_CONFIDENCE_ACTION_GUARD_RE, raw, intent):
        return ACTION_ROUTER_REPLY
    if HOTSPOT_SECRET_STATUS_RE.search(raw):
        return HOTSPOT_STATUS_REPLY
    if WHISPLAY_DOCTOR_RE.search(raw):
        return WHISPLAY_DOCTOR_REPLY
    if WHISPLAY_STATUS_RE.search(raw):
        return WHISPLAY_STATUS_REPLY
    if LOCAL_CONTROL_PRIORITY_RE.search(raw):
        return LOCAL_CONTROL_REPLY
    if CASUAL_NETWORK_TOPIC_RE.search(raw):
        return LOCAL_REPLIES[len(raw or "") % len(LOCAL_REPLIES)]
    if _intent_match(HOTSPOT_STATUS_RE, raw, intent):
        return HOTSPOT_STATUS_REPLY
    if LOCAL_CONTROL_RE.search(raw):
        return LOCAL_CONTROL_REPLY
    if CAPABILITY_READY_RE.search(raw):
        return CAPABILITY_READY_REPLY
    if SERVICE_STATUS_RE.search(raw):
        return SERVICE_STATUS_REPLY
    if TTS_PRIVACY_QUIET_RE.search(raw) and not _info_followup_match(raw, intent):
        return TTS_PRIVACY_QUIET_REPLY
    if TTS_POLICY_COMPARISON_RE.search(raw):
        return FROST_TTS_DECISION_REPLY
    if _intent_match(LOW_BATTERY_PLAYBACK_RE, raw, intent):
        return LOW_BATTERY_PLAYBACK_REPLY
    if _router_priority_match(raw, intent):
        return ACTION_ROUTER_REPLY
    if _intent_match(FAILURE_GUARDRAIL_RE, raw, intent):
        return FAILURE_GUARDRAIL_REPLY
    if _intent_match(LAST_REPLY_RE, raw, intent):
        return LAST_REPLY_REPLY
    if _intent_match(PREVIOUS_UTTERANCE_CANCEL_RE, raw, intent):
        return "收到，上一句先作废；我不会按那条继续执行。若已开始播放，请再说停播。"
    if _intent_match(ACTION_STATUS_RE, raw, intent):
        return ACTION_STATUS_REPLY
    if _intent_match(FROST_TTS_DECISION_RE, raw, intent) and not _info_followup_match(raw, intent):
        return FROST_TTS_DECISION_REPLY
    if _intent_match(DJ_BRANCH_RETURN_RE, raw, intent):
        return DJ_BRANCH_RETURN_REPLY
    if (
        NO_ACTION_NEXT_CITY_PLAYLIST_REASON_RE.search(raw)
        or NO_ACTION_PREVIOUS_CITY_PLAYLIST_REASON_RE.search(raw)
        or _intent_match(NEXT_CITY_PLAYLIST_REASON_RE, raw, intent)
        or _intent_match(PREVIOUS_CITY_PLAYLIST_REASON_RE, raw, intent)
        or _intent_match(PREVIOUS_CITY_PLAYLIST_FOLLOWUP_RE, raw, intent)
    ):
        return PLAYLIST_STATUS_REPLY
    if _intent_match(CHAT_FLOW_RE, raw, intent):
        return "Frost 对话会写回屏幕：用户消息、回复、TTS 判断和回主线状态都会保留；24H Radio 主线不被打断。"
    if _intent_match(FAILURE_GUARDRAIL_RE, raw, intent):
        return FAILURE_GUARDRAIL_REPLY
    if _intent_match(ACTION_ROUTER_RE, raw, intent):
        return ACTION_ROUTER_REPLY
    if _intent_match(NATURAL_LANGUAGE_RE, raw, intent):
        return NATURAL_LANGUAGE_REPLY
    if _intent_match(MEMORY_BOUNDARY_RE, raw, intent):
        return MEMORY_BOUNDARY_REPLY
    if NO_ACTION_CURRENT_STATUS_RE.search(raw):
        return CURRENT_TRACK_STATUS_REPLY
    if NO_ACTION_PREVIOUS_TRACK_STATUS_RE.search(raw):
        return CURRENT_TRACK_STATUS_REPLY
    if _intent_match(CURRENT_LOCATION_FOLLOWUP_RE, raw, intent):
        return CURRENT_TRACK_STATUS_REPLY
    if _intent_match(CURRENT_TRACK_FOLLOWUP_RE, raw, intent):
        return CURRENT_TRACK_STATUS_REPLY
    if NO_ACTION_NEXT_CITY_STORY_RE.search(raw):
        return NEXT_CITY_STORY_REPLY
    if NO_ACTION_PREVIOUS_CITY_STORY_RE.search(raw):
        return PREVIOUS_CITY_STORY_REPLY
